def record_feedback(
    self,
    result: dict[str, Any],
    latency_ms: float,
) -> None:
    """Record resonance quality signals for adaptive tuning.

    Fire-and-forget: exceptions are logged, never propagated.
    """
    try:
        patterns = result.get("patterns", [])
        coherence = result.get("bridge_result", {}).get("coherence", 0.0)
        self.interaction_log.append({
            "type": "feedback",
            "latency_ms": latency_ms,
            "pattern_count": len(patterns),
            "coherence": coherence,
        })
    except Exception:
        logger.debug("record_feedback failed silently", exc_info=True)

def _passes_luhn(digits: str) -> bool:
    """Validate a digit string against the Luhn algorithm (ISO/IEC 7812-1)."""
    cleaned = digits.replace("-", "").replace(" ", "").replace(".", "")
    if not cleaned.isdigit() or len(cleaned) < 13:
        return False
    total = 0
    for i, ch in enumerate(reversed(cleaned)):
        n = int(ch)
        if i % 2 == 1:
            n *= 2
            if n > 9:
                n -= 9
        total += n
    return total % 10 == 0
